import * as T from 'three';import {CURLING_GEOMETRY as G,CURLING_AID as A,curlingHeldStone} from './curling-layout.js';import {CURLING_PHYSICS as P} from './curling-model.js';
export function buildCurlingView(parent){
 const machine=new T.Group();machine.name='schoolGym.curling';parent?.add(machine);const geometries=new Map(),materials=new Map(),solids=[];let alive=true;
 const geometry=(key,make)=>{if(!geometries.has(key))geometries.set(key,make());return geometries.get(key);},material=c=>{if(!materials.has(c))materials.set(c,new T.MeshStandardMaterial({color:c,roughness:.82}));return materials.get(c);};
 function box(w,h,d,c,x,y,z,name){const m=new T.Mesh(geometry(`b${w},${h},${d}`,()=>new T.BoxGeometry(w,h,d)),material(c));m.position.set(x,y,z);m.name=name;machine.add(m);return m;}
 const ice=box(4.1,.01,23.05,'#e8f1ea',0,.007,9.175,'schoolGym.curling.ice');
 for(const x of[-2.125,2.125])solids.push(box(.15,.20,20.5,'#7faaa0',x,.112,10.25,'schoolGym.curling.rail'));solids.push(box(4.4,.20,.15,'#7faaa0',0,.112,20.575,'schoolGym.curling.end'));
 for(const[r,c,y]of[[1.6,'#88b6bb',.015],[1,'#f5ead3',.018],[.45,'#cd9680',.021]]){const mesh=new T.Mesh(geometry('ring'+r,()=>new T.CylinderGeometry(r,r,.002,48)),material(c));mesh.position.set(0,y,17);mesh.name='schoolGym.curling.house';machine.add(mesh);}
 const rearCatch=box(4.1,.14,.15,'#7faaa0',0,.082,.575,'schoolGym.curling.rear-catch');rearCatch.visible=false;
 for(const z of[.28,3])box(4.08,.003,.025,'#b3c6bb',0,.016,z,'schoolGym.curling.line');
 function stone(team,id){const root=new T.Group();root.name='schoolGym.curling.stone.'+id;machine.add(root);const base=new T.Mesh(geometry('disk',()=>new T.CylinderGeometry(P.radius,P.radius,G.stoneHeight,32)),material(team==='target'?'#c7a46f':'#638fbc'));base.position.y=G.floorY+G.stoneHeight/2;root.add(base);const handle=new T.Mesh(geometry('handle',()=>new T.BoxGeometry(G.handleWidth,G.handleHeight,G.handleDepth)),material(team==='target'?'#e3c58d':'#9bb8d4'));handle.position.y=G.handleY;root.add(handle);for(const x of[-.115,.115]){const post=new T.Mesh(geometry('post',()=>new T.BoxGeometry(.04,.09,.065)),handle.material);post.position.set(x,.237,0);root.add(post);}return{root,base,handle};}
 const stones=Array.from({length:6},(_,i)=>stone(i<2?'target':'player',i)),heldStone=stone('player','held');for(const s of stones)s.root.visible=false;heldStone.root.visible=false;
 const aim=box(.028,.003,2.3,'#d19c60',.48,.023,2,'schoolGym.curling.aim');aim.visible=false;
 const aidRoot=new T.Group();aidRoot.name='schoolGym.curling.delivery-aid';aidRoot.visible=false;machine.add(aidRoot);
 const grip=new T.Mesh(geometry('aid-grip',()=>new T.BoxGeometry(A.gripWidth,A.gripHeight,A.gripDepth)),material('#ab8970'));grip.name=aidRoot.name+'.grip';grip.position.set(A.gripX,A.gripY,A.gripBackZ+A.gripDepth/2);aidRoot.add(grip);
 const head=new T.Mesh(geometry('aid-head',()=>new T.BoxGeometry(A.headWidth,A.headHeight,A.headDepth)),material('#789b9a'));head.name=aidRoot.name+'.head';head.position.set(A.headX,A.headY,A.headZ);aidRoot.add(head);
 const direction=head.position.clone().sub(grip.position),shaft=new T.Mesh(geometry('aid-shaft',()=>new T.CylinderGeometry(.016,.016,direction.length(),12)),material('#ab8970'));shaft.name=aidRoot.name+'.shaft';shaft.position.copy(grip.position).add(head.position).multiplyScalar(.5);shaft.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),direction.clone().normalize());aidRoot.add(shaft);
 const aid={root:aidRoot,grip,head,shaft,length:direction.length()},shoulder=new T.Vector3(.38,.685,.025),axis=new T.Vector3(1,0,0);
 function hold(f){heldStone.root.visible=!!f.holding;const p=curlingHeldStone(f);heldStone.root.position.set(p.x,0,p.z);aim.visible=!!f.holding;aim.position.set(p.x+Math.sin(f.aim??0)*1.15,.023,p.z+Math.cos(f.aim??0)*1.15);aim.rotation.y=f.aim??0;if(f.root){const q=new T.Quaternion().setFromAxisAngle(axis,(A.carryAngle-A.pushAngle)*(f.aidLift??0));aidRoot.visible=true;aidRoot.quaternion.copy(q);aidRoot.position.copy(shoulder).sub(shoulder.clone().applyQuaternion(q)).add(new T.Vector3(f.root.x,f.root.y,f.root.z));}machine.updateWorldMatrix(true,true);}
 function update(s){rearCatch.visible=['sliding','settled','complete'].includes(s.state);for(let i=0;i<stones.length;i++){const data=s.stones.find(x=>x.id===i);stones[i].root.visible=!!data;if(data)stones[i].root.position.set(data.x,0,data.z);}hold(s.frame);}
 return{machine,ice,rearCatch,solids,stones,heldStone,aid,aim,hold,update,dispose(){if(!alive)return;alive=false;machine.removeFromParent();for(const g of geometries.values())g.dispose();for(const m of materials.values())m.dispose();}};
}
